def predict(probe):
    # Beliefs:
    # - Most characters pass through unchanged [E1, E2, E3]
    # - Lowercase 'p' becomes 'k' when preceded by lowercase 's' [E2: "spaces"->"skaces"]
    # - Lowercase 'p' becomes 'k' when followed by lowercase 'l' [E2,E3: "example"->"examkle", "Example"->"Examkle"]
    # - Uppercase 'P' is not changed [E1: "bananaUPPER" unchanged]
    # - Other letters (s, l themselves) unchanged [E2,E3]
    outputs = []
    for s in probe["inputs"]:
        chars = list(s)
        n = len(chars)
        for i, c in enumerate(chars):
            if c == 'p':
                prev_s = (i > 0 and chars[i-1] == 's')
                next_l = (i+1 < n and chars[i+1] == 'l')
                if prev_s or next_l:
                    chars[i] = 'k'
        outputs.append(''.join(chars))
    return {"outputs": outputs}
